from rllab.core import SOLO
from rllab.runs import RunRecord

SYMBOL = "train.train"


def test_samples_follow_the_schema(codec):
    codec.assert_samples_valid(SYMBOL)


def test_fake_passes_the_train_check(codec, tmp_path):
    fake = codec.fake(SYMBOL)
    record = codec.sample(SYMBOL, "corridor_complete_3", RunRecord)
    envs, agents = codec.fake("core.Env"), codec.fake("core.Agent")
    env_recording = codec.sample("envs.Corridor", "goal_9", envs.EnvRecording)
    agent = agents.ReplayAgent(
        codec.sample("agents.TabularAgent", "corridor_5", agents.AgentRecording)
    )
    trained = fake.check_train(
        fake.make_train(record),
        lambda: envs.ReplayEnv(env_recording),
        {SOLO: agent},
        record.settings,
        tmp_path,
    )
    assert len(trained.curve) == 3

